def oracle(m):
 k=m['kind']
 if k=='strip':
  valid=[]
  for ids in permutations(m['strips'],m['use']):
   ss=[m['strips'][i] for i in ids]
   if ss[0][1]=='START' and ss[-1][2]=='END' and all(a[2]==b[1] for a,b in zip(ss,ss[1:])) and (m['pin_middle'] is None or ss[1][0]==m['pin_middle']):valid.append(list(ids))
  assert valid==m['expected'];return dict(valid_chains=valid,numerals=[''.join(m['strips'][i][0] for i in ids) for ids in valid],permutations_checked=len(list(permutations(m['strips'],m['use']))))
 if k=='partial_digits':
  solutions=[]
  for a,b,c,d in product(range(10),repeat=4):
   n=30+a
   if n*4==100+10*b+6 and n*20==700+10*c and n*24==900+10*d+6:solutions.append([a,b,c,d])
  assert solutions==m['expected'];return dict(digit_assignments_checked=10000,solutions=solutions)
 if k=='partial_factors':
  candidates=[]
  for a,b in product(range(10),range(1,10)):
   n=30+a
   if n*3==m['unit_product'] and n*(10*b)==m['tens_product']:candidates.append([n,10*b+3,n*(10*b+3)])
  assert candidates==[m['expected']];return dict(candidates=candidates,ones_partial=93,shifted_tens_partial=620)
 if k=='overlap':
  bars=[sorted(v) for v in m['bars']];lengths=[b-a for a,b in bars];common_len=max(0,min(v[1] for v in bars)-max(v[0] for v in bars));union=sum(lengths)-common_len
  # Independently count covered unit cells for these exact integer endpoints.
  sets=[set(range(a,b)) for a,b in bars];assert len(sets[0]&sets[1])==common_len and len(sets[0]|sets[1])==union;assert lengths==m['expected_lengths'] and common_len==m['expected_overlap'] and union==m['expected_union'];return dict(normalized_intervals=bars,lengths=lengths,common=common_len,union=union,unit_cell_reconstruction_pass=True)
 if k=='angles':
  out=[]
  for a,b in combinations(m['directions'],2):
   gap=abs(Fraction(m['directions'][a])-Fraction(m['directions'][b]));gap=min(gap,360-gap)
   if gap<180 or (gap==180 and m['include_straight']):out.append([a,b,int(gap)])
  assert out==m['expected'];return dict(all_counted_ray_pairs=out,count=len(out),straight_included=m['include_straight'])
 if k=='collinear':
  out=[];trials=[]
  for ids in combinations(m['points'],3):
   a,b,c=[m['points'][i] for i in ids];det=(Fraction(b[0])-a[0])*(Fraction(c[1])-a[1])-(Fraction(b[1])-a[1])*(Fraction(c[0])-a[0]);trials.append([list(ids),str(det)])
   if not det:out.append(list(ids))
  canonical=lambda rows:sorted(tuple(sorted(v)) for v in rows)
  assert canonical(out)==canonical(m['expected']);return dict(all_triples_determinants=trials,zero_determinant_triples=out,count=len(out),oracle_coordinate_enrichment_not_student_algebra=True)
 if k=='matrix_unique':
  candidates=[list(v) for v in product(['đỏ','xanh'],['tròn','vuông','tam giác']) if v[0]=='xanh' and v[1]=='tam giác'];assert candidates==[m['expected']];return dict(all_cell_values_checked=6,solutions=candidates)
 if k=='matrix_ambiguous':
  solutions=[]
  for left,right in product(product(['đỏ','xanh'],['tròn','vuông']),repeat=2):
   if left[0]=='đỏ' and right[0]=='xanh' and sorted([left[1],right[1]])==sorted(['tròn','vuông']):solutions.append([list(left),list(right)])
  assert solutions==m['expected_rows'];return dict(bottom_row_assignments_checked=16,solutions=solutions)
 raise ValueError(k)

