 oldq={json.loads(b)['problem'] for f in ['current_sources.jsonl','release/accepted_cases.jsonl'] for b in (common.OLD/f).read_bytes().splitlines()};oldq.update(r['problem'] for r in allnew);assert not any(r['problem'] in oldq for r in ROWS)
